/// Functions in this module (differential entry points; not admitted to any selector).
pub const ROOTS: [u32; 7] = [
    0x25280, 0x25710, 0x25e40, 0x25ff0, 0x26320, 0x263e0, 0x26740,
];

/// Differential entry: runs the translation of `va`. True when `va` belongs to this module.
#[allow(unused_variables)]
pub fn run<M: GuestMemory, C: GuestCall>(
    va: u32,
    m: &mut M,
    guest: &mut C,
    regs: &mut ExtRegisters,
) -> bool {
    match va {
        0x25280 => game_save_file_load_verify(m, guest, regs),
        0x25710 => game_save_signature_finish(m, guest, regs),
        0x25e40 => game_save_game_find_enumerate(m, guest, regs),
        0x25ff0 => game_content_find_enumerate(m, guest, regs),
        0x26320 => game_save_slots_enumerate_for_verify_with_bounded_copy(m, guest, regs),
        0x263e0 => game_save_game_write(m, guest, regs),
        0x26740 => game_content_write(m, guest, regs),
        _ => return false,
    }
    true
}
